style.css:
@-moz-document domain("youtube.com"), url("https://www.youtube.com/") {
/* Set the background image */
    body {
        background: url('https://i.imgur.com/F5MJu4a.jpeg') no-repeat center center fixed;
        background-size: cover;
    }

    /* Make all text light blue */
    * {
        color: #A9D9FF !important; /* Light blue text */
    }

    /* Ensure video titles and comments are visible */
    h1.title, 
    h1.ytd-watch-metadata, 
    #container h1, 
    yt-formatted-string.title,
    #video-title, 
    #video-title-link, 
    .ytd-video-primary-info-renderer, 
    .ytd-comment-renderer, 
    .ytd-expander, 
    #description, 
    #content-text, 
    #author-text, 
    .ytd-thumbnail-overlay-time-status-renderer {
        color: #A9D9FF !important;
    }

    /* Make sidebar and menu text light blue */
    #guide-inner-content, 
    #guide-title, 
    #sections, 
    .ytd-guide-section-renderer, 
    .ytd-guide-entry-renderer {
        color: #A9D9FF !important;
    }
}
